#include "process/ProcessManager.h"
#include <vector>
#include <utility>
namespace lvk::process { ProcessManager::~ProcessManager(){stop();} bool ProcessManager::start(const std::wstring&e,const std::wstring&a,const std::wstring&cwd,std::function<void(const std::string&)> cb){if(running_)return false;SECURITY_ATTRIBUTES sa{sizeof(sa),nullptr,TRUE};HANDLE in=nullptr; if(!CreatePipe(&outRead_,&in,&sa,0))return false;SetHandleInformation(outRead_,HANDLE_FLAG_INHERIT,0);std::wstring line=L"\""+e+L"\" "+a;std::vector<wchar_t>b(line.begin(),line.end());b.push_back(0);STARTUPINFOW si{sizeof(si)};si.dwFlags=STARTF_USESHOWWINDOW|STARTF_USESTDHANDLES;si.wShowWindow=SW_HIDE;si.hStdOutput=in;si.hStdError=in;PROCESS_INFORMATION pi{};const bool hasPath=e.find_first_of(L"\\/")!=std::wstring::npos;if(!CreateProcessW(hasPath?e.c_str():nullptr,b.data(),nullptr,nullptr,TRUE,CREATE_NO_WINDOW|CREATE_NEW_PROCESS_GROUP,nullptr,cwd.empty()?nullptr:cwd.c_str(),&si,&pi)){CloseHandle(in);CloseHandle(outRead_);outRead_=nullptr;return false;}CloseHandle(in);CloseHandle(pi.hThread);process_=pi.hProcess;pid_=pi.dwProcessId;running_=true;reader_=std::thread(&ProcessManager::read,this,outRead_,std::move(cb));return true;}void ProcessManager::read(HANDLE pipe,std::function<void(const std::string&)> cb){char b[4096];DWORD n=0;while(ReadFile(pipe,b,sizeof(b),&n,nullptr)&&n)cb(std::string(b,n));CloseHandle(pipe);outRead_=nullptr;}bool ProcessManager::stop(){if(!process_)return true;GenerateConsoleCtrlEvent(CTRL_BREAK_EVENT,pid_);if(WaitForSingleObject(process_,3000)==WAIT_TIMEOUT)TerminateProcess(process_,1);WaitForSingleObject(process_,3000);CloseHandle(process_);process_=nullptr;running_=false;pid_=0;if(reader_.joinable())reader_.join();return true;}bool ProcessManager::running()const{return process_&&WaitForSingleObject(process_,0)==WAIT_TIMEOUT;}unsigned long ProcessManager::pid()const{return pid_;}HANDLE ProcessManager::processHandle()const noexcept{return process_;} }
